INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C006', 'ボックス呼吸', ARRAY['ボックス呼吸法','Box Breathing']::text[], 'practice', '現代呼吸法', '保息を含む概要・安全確認用', '集中・緊張調整として紹介', ARRAY['鼻から4秒吸う。','4秒息を止める。','4秒かけて吐く。','4秒息を止める。']::text[], ARRAY['P24','P25','P26','P082','P083','P084','P187','P188','P186','P205']::text[], ARRAY['K016','K017','K008','K013','K014','K015']::text[], ARRAY['S002','S004']::text[], false, false, '[{"variant_id":"C006-V01","label":"第6章の基本手順","source_passage_ids":["P082"],"steps_editorial":["鼻から4秒吸う。","4秒息を止める。","4秒かけて吐く。","4秒息を止める。"],"dose_source_text":"4〜5サイクル、約1〜2分","breath_hold":true,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C006-V02","label":"第7章のボックス呼吸","source_passage_ids":["P083","P187"],"steps_editorial":["吸う・止める・吐く・止めるを各4秒。"],"dose_source_text":"3〜5セット","breath_hold":true,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C006-V03","label":"原稿内のやさしいボックス（等間隔ではない）","source_passage_ids":["P084","P187"],"steps_editorial":["2秒吸う・1秒休む・3秒吐く・1秒休む。"],"dose_source_text":"3〜5セット（7-11の図で追加確認）","breath_hold":true,"route":null,"status":"overview_only","auto_selection_allowed":false},{"variant_id":"C006-V04","label":"7-12 本番3分前の例","source_passage_ids":["P188"],"steps_editorial":["吸う・止める・吐く・止めるを各4秒。"],"dose_source_text":"3〜4セット。本番3分前は開始する場面。","breath_hold":true,"route":null,"status":"overview_only","auto_selection_allowed":false},{"variant_id":"C006-V05","label":"導入図の名称未確定例","source_passage_ids":["P186"],"steps_editorial":["4秒吸う、4秒止める、6〜8秒吐く、4秒止めるという図示。"],"dose_source_text":"数分間という記載のみ。等時間の本文手順とは不一致。","breath_hold":true,"route":null,"status":"withheld_conflicting_source","auto_selection_allowed":false},{"variant_id":"C006-V06","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"1〜3分。個別手順は一覧に未記載。","breath_hold":true,"route":null,"status":"overview_only","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I023","rule":"第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。"},{"issue_id":"I024","rule":"ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"},{"issue_id":"I044","rule":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C007', '4-7-8呼吸', ARRAY['478呼吸','4–7–8呼吸']::text[], 'practice', '現代呼吸法', '比較対象', '就寝前・リラックスとして紹介', '{}', ARRAY['P24','P25','P26','P085']::text[], ARRAY['K016','K017','K003','K013','K014','K015']::text[], ARRAY['S002','S004']::text[], false, false, '[{"variant_id":"C007-V01","label":"第3章ファイルの4・7・8呼吸法（手順矛盾あり）","source_passage_ids":["P085"],"steps_editorial":["鼻から4秒吸う。","原文に「7秒間、息を止めずにキープ」とある。","口をすぼめ8秒吐く。"],"dose_source_text":"4〜8セット","breath_hold":null,"route":null,"status":"blocked_ambiguous_source","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I025","rule":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C008', '長い呼気の呼吸', ARRAY['長く吐く呼吸','吐く息を長くする呼吸']::text[], 'practice', '本教材の基本呼吸法', '実践', '落ち着く・休息として紹介', ARRAY['椅子に座るか仰向けになり、肩の力を抜く。','鼻から自然に吸い、鼻または口から吸うより長く吐く。','3秒吸う・5秒吐く、または4秒吸う・6秒吐くという教材の例を使う。']::text[], ARRAY['P24','P25','P26','P081','P116','P120','P175','P187','P188','P227','P205']::text[], ARRAY['K016','K017','K013','K014','K015','K019','K034']::text[], ARRAY['S002','S004']::text[], false, false, '[{"variant_id":"C008-V01","label":"第6章の基本手順","source_passage_ids":["P081"],"steps_editorial":["椅子に座るか仰向けになり、肩の力を抜く。","鼻から自然に吸い、鼻または口から吸うより長く吐く。","3秒吸う・5秒吐く、または4秒吸う・6秒吐くという教材の例を使う。"],"dose_source_text":"5〜10呼吸","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V02","label":"第14章の長い呼気","source_passage_ids":["P116"],"steps_editorial":["鼻から3〜4秒吸う。","口から6〜8秒細く長く吐く。"],"dose_source_text":"3〜5回","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V03","label":"6-9 リカバリーの例","source_passage_ids":["P175"],"steps_editorial":["吸う4秒、吐く6〜8秒という原稿の例。","肋骨やお腹の動きを感じ、深さを強制しない。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V04","label":"7-11 保息を入れない代替例","source_passage_ids":["P187"],"steps_editorial":["3秒吸う。","5秒吐く。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V05","label":"7-12 本番10分前の例","source_passage_ids":["P188"],"steps_editorial":["4秒吸い、6秒吐く。"],"dose_source_text":"5〜10呼吸。本番10分前は開始する場面であり、10分間継続の意味ではない。","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V06","label":"14-3 面接・試験の例","source_passage_ids":["P227"],"steps_editorial":["鼻から3秒吸い、口から6〜8秒吐く。","面接では一度吐いてから答え、試験では問題へ戻る前の一呼吸として紹介。"],"dose_source_text":null,"breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C008-V07","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"1〜3分。吸気呼気比はこの一覧に未記載。","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I008","rule":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。"},{"issue_id":"I012","rule":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。"},{"issue_id":"I013","rule":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。"},{"issue_id":"I022","rule":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。"},{"issue_id":"I029","rule":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。"},{"issue_id":"I043","rule":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。"},{"issue_id":"I044","rule":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
