INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C011', '呼吸カウント集中法', '{}', 'practice', '教材内の実践', '実践', '集中・注意を戻す', ARRAY['椅子に楽に座り、鼻から自然に呼吸する。','吐く息で1、次の吐く息で2と数える。','10まで数えたら1に戻る。','数を忘れたら1から。考え事に気づいたら呼吸へ戻る。']::text[], ARRAY['P090','P197','P205']::text[], ARRAY['K008','K035','K036','K037','K078']::text[], ARRAY['S002','S004']::text[], false, false, '[{"variant_id":"C011-V01","label":"7-7 吸気・呼気で同じ数を数える例","source_passage_ids":["P197"],"steps_editorial":["姿勢を整え、自然な呼吸をそのまま観察する。","本文の例は吸って1、吐いて1、吸って2、吐いて2。","考え事に気づいたら呼吸と数えることへ戻る。"],"dose_source_text":"1〜3分。何番まで数えるかはこの図に未記載。","breath_hold":false,"route":null,"status":"review_draft","auto_selection_allowed":false},{"variant_id":"C011-V02","label":"第2部まとめの時間一覧","source_passage_ids":["P205"],"steps_editorial":[],"dose_source_text":"3分。数え方は一覧に未記載。","breath_hold":false,"route":null,"status":"summary_only","auto_selection_allowed":false}]'::jsonb, '[{"issue_id":"I045","rule":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_catalog (catalog_id, name, aliases, category_id, tradition_category, curriculum_mode, purpose_in_source, steps_editorial, source_passage_ids, related_knowledge_ids, related_safety_ids, production_ready, overview_only, variants, answer_constraints, editorial_policy_version) VALUES ('C012', '脱力呼吸', '{}', 'practice', '教材内の実践', '実践', '肩まわりの力みに気づく', ARRAY['座るか仰向けになる。','肩を5秒すくめ、ストンと下ろす。','鼻から4秒吸い、口をすぼめて8秒吐く。']::text[], ARRAY['P091']::text[], ARRAY['K003','K026','K027']::text[], ARRAY['S004']::text[], false, false, '[]'::jsonb, '[{"issue_id":"I025","rule":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。"}]'::jsonb, '5.0') ON CONFLICT (catalog_id) DO NOTHING;
